INSERT INTO courses (slug, title, subtitle, description, discipline_id, level, instructor_name, instructor_role, updated, hue, position) VALUES ('liquid-rocket-engines', 'Liquid Rocket Engines', 'From the thrust equation to a sized, cooled and stable thrust chamber.', 'Learn how a liquid-propellant rocket engine turns propellant into thrust, and how engineers size the chamber, nozzle and injector, keep the walls alive, feed the propellants and stop the combustion from shaking the engine apart. The course ends with a complete sizing of an 18 kN LOX/RP-1 engine, the class of engine the Centre builds.', 'liquid-engines', 'Intermediate', 'DUT Space Science Centre', 'Propulsion team', '2026-11', 150, 1);
INSERT INTO course_also_disciplines (course_slug, discipline_id, position) VALUES ('liquid-rocket-engines', 'structures-vibration', 0);
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'outcome', 0, 'Use the thrust equation, specific impulse, c* and CF to compare engines and size a thrust chamber');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'outcome', 1, 'Choose propellants, mixture ratio and an engine cycle for a given mission and thrust class');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'outcome', 2, 'Size the throat, chamber, nozzle and injector orifices of a small LOX/RP-1 engine by hand');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'outcome', 3, 'Estimate wall heat flux and coolant temperature rise, and choose a cooling method');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'outcome', 4, 'Size feed pressures and pump power, and check that a pump will not cavitate');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'outcome', 5, 'Recognise chugging, buzz and screech, and explain how pogo couples engine and structure');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'prerequisite', 0, 'Newtonian mechanics and the ideal-gas law');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'prerequisite', 1, 'Basic thermodynamics: enthalpy, isentropic flow, the speed of sound');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'prerequisite', 2, 'Comfort with logarithms and square roots on a calculator');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'audience', 0, 'Engineering students joining the Centre''s engine test programme');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'audience', 1, 'Engineers moving from another discipline into propulsion');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('liquid-rocket-engines', 'audience', 2, 'Anyone who wants to read an engine datasheet critically');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('liquid-rocket-engines', 'm1', 'Performance and architecture', 'What an engine produces, which propellants make it, and how the propellants get into the chamber.', 0);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'thrust-isp', 'm1', 'Thrust, specific impulse and c*', 30, 'The three numbers that describe any rocket engine, and how they connect.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 0, 'h', '{"text":"Where thrust comes from"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 1, 'p', '{"text":"A rocket engine throws mass backwards and is pushed forwards. The force is the rate at which the exhaust gains momentum, plus a correction for the pressure at the nozzle exit not matching the air outside."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 2, 'eq', '{"text":"F = \\dot m\\, v_e + (p_e - p_a)\\,A_e","name":"Thrust equation","caption":"Momentum thrust plus pressure thrust"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 3, 'ul', '{"items":["**$\\dot m$** is the total propellant mass flow (oxidiser plus fuel), in kg/s.","**$v_e$** is the exhaust velocity at the nozzle exit plane, in m/s.","**$(p_e - p_a)A_e$** is the pressure thrust. It is zero when the nozzle is perfectly expanded ($p_e = p_a$), positive when under-expanded and negative when over-expanded."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 4, 'h', '{"text":"Specific impulse"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 5, 'p', '{"text":"Thrust alone does not say how efficiently propellant is used. **Specific impulse** is thrust per unit weight flow of propellant, and it has units of seconds."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 6, 'eq', '{"text":"I_{sp} = \\frac{F}{\\dot m\\, g_0} = \\frac{c_{eff}}{g_0}, \\qquad g_0 = 9.80665\\ \\mathrm{m/s^2}","name":"Specific impulse"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 7, 'p', '{"text":"Isp is what the rocket equation cares about: $\\Delta v = I_{sp}\\, g_0 \\ln(m_0/m_f)$. A 300 s engine and a mass ratio of 4 give $\\Delta v \\approx 4.08$ km/s."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 8, 'callout', '{"kind":"key","title":"Quote the pressure","text":"Isp depends on the ambient pressure through the pressure-thrust term. A booster engine is quoted at sea level and in vacuum, and the two can differ by 10 to 20 percent. Always say which one you mean."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 9, 'h', '{"text":"Characteristic velocity and thrust coefficient"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 10, 'p', '{"text":"Isp mixes two different things: how well the propellants burn, and how well the nozzle expands the gas. Engineers separate them."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 11, 'eq', '{"text":"c^* = \\frac{p_c A_t}{\\dot m}, \\qquad C_F = \\frac{F}{p_c A_t}, \\qquad I_{sp} = \\frac{c^*\\, C_F}{g_0}","name":"c* and CF"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 12, 'ul', '{"items":["**$c^*$** (characteristic velocity) depends on the propellants, mixture ratio and combustion efficiency, not on the nozzle. For LOX/RP-1 it is about 1 700 to 1 800 m/s.","**$C_F$** depends on the nozzle area ratio, the gas properties and the pressure ratio, not on the combustion. Values of 1.3 to 1.9 are typical.","Measured $c^*$ divided by the ideal value is the **$c^*$ efficiency**, the best single test of injector and chamber quality. Good small engines reach 95 to 98 percent."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'thrust-isp', 13, 'table', '{"head":["Quantity","Set by","Tells you about"],"rows":[["$c^*$","Propellants, O/F, combustion","Injector and chamber quality"],["CF","Nozzle shape and pressure ratio","Nozzle quality"],["Isp","$c^*$ and CF together","Overall efficiency"]]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'thrust-isp', 0, 'Thrust is $\dot m v_e + (p_e - p_a)A_e$, and Isp is thrust divided by weight flow.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'thrust-isp', 1, 'Isp changes with altitude; always say sea level or vacuum.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'thrust-isp', 2, '$c^*$ measures the combustion, CF measures the nozzle, and Isp is their product divided by g0.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('liquid-rocket-engines', 'thrust-isp', 0, 'Rocket Propulsion Elements, chapters 2 and 3', 'Sutton and Biblarz', NULL, 'The standard textbook treatment of these definitions');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'propellants', 'm1', 'Propellants and mixture ratio', 30, 'Why LOX/RP-1, LOX/methane, LOX/hydrogen and storables behave so differently.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 0, 'h', '{"text":"What makes a good propellant pair"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 1, 'p', '{"text":"Chemistry sets the energy released per kilogram. Physics then decides how easy the pair is to store, pump and cool. No pair wins on everything, so the choice is a trade."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 2, 'table', '{"head":["Pair","Vacuum Isp (typical)","Bulk density (kg/m³)","Typical O/F","Main trait"],"rows":[["LOX / LH2","430 to 460 s","about 360","5 to 6","Highest Isp, huge tanks, cryogenic fuel"],["LOX / RP-1","330 to 350 s","about 1 020","2.2 to 2.8","Dense, cheap, easy to handle, risk of coking"],["LOX / methane","350 to 370 s","about 820","3.2 to 3.6","Clean burning, reusable engines, cryogenic"],["N2O4 / UDMH","320 to 340 s","about 1 150","2.0 to 2.5","Hypergolic and storable, toxic"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 3, 'h', '{"text":"Mixture ratio"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 4, 'p', '{"text":"The **oxidiser-to-fuel ratio** O/F is the ratio of oxidiser mass flow to fuel mass flow. Combustion temperature peaks near stoichiometric, but the best Isp is reached **fuel-rich**, because lighter exhaust molecules give a higher exhaust velocity for the same energy."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 5, 'eq', '{"text":"\\dot m_{ox} = \\dot m\\,\\frac{O/F}{1 + O/F}, \\qquad \\dot m_{f} = \\frac{\\dot m}{1 + O/F}","name":"Splitting the total flow"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 6, 'p', '{"text":"For $\\dot m = 7.6$ kg/s and O/F = 2.3, the oxidiser flow is 5.3 kg/s and the fuel flow is 2.3 kg/s."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 7, 'callout', '{"kind":"key","title":"Density matters too","text":"A stage is limited by tank volume as much as by Isp. Dense propellants make smaller, lighter tanks, so a lower-Isp dense pair can beat a higher-Isp light one in a first stage. That is why hydrogen is mostly used in upper stages."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'propellants', 8, 'callout', '{"kind":"warn","title":"Real exhaust is not the ideal one","text":"Chemical equilibrium programs (CEA, RPA) give ideal $c^*$, Isp and temperatures. A real engine delivers 90 to 98 percent of the ideal $c^*$, and the nozzle loses a few more percent."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'propellants', 0, 'Isp, density, handling and cost all matter; the best pair depends on the stage and the mission.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'propellants', 1, 'O/F for best Isp is fuel-rich of stoichiometric; best density-Isp is a little richer in oxidiser.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'propellants', 2, 'Total flow splits as $\dot m_{ox} = \dot m\,(O/F)/(1+O/F)$ and $\dot m_f = \dot m/(1+O/F)$.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'cycles', 'm1', 'Engine cycles', 35, 'Pressure-fed, gas generator, expander, staged combustion: how the energy to pump comes about.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 0, 'h', '{"text":"The pumping problem"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 1, 'p', '{"text":"Propellants must enter the chamber at a pressure above the chamber pressure. The **engine cycle** decides where that pressure comes from."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 2, 'h', '{"text":"Pressure-fed"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 3, 'p', '{"text":"The tanks are pressurised, usually with helium, and the propellants push themselves into the chamber. There are no turbines, so the engine is simple and very reliable. The price is heavy, thick-walled tanks, which limits chamber pressure to about 1 to 3 MPa and keeps the Isp modest."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 4, 'h', '{"text":"Pump-fed cycles"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 5, 'p', '{"text":"Pumps raise the pressure so the tanks stay thin and light, and the chamber pressure can be much higher. The cycles differ in what drives the turbine."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 6, 'table', '{"head":["Cycle","What drives the turbine","Chamber pressure","Example"],"rows":[["Gas generator","A small side burner; exhaust is dumped overboard","about 7 to 10 MPa","Merlin 1D"],["Expander","Fuel heated in the cooling jacket, then expanded","about 3 to 8 MPa","RL10"],["Staged combustion","Preburner exhaust is routed into the main chamber","up to about 25 MPa","RD-180"],["Full-flow staged","Both propellants pass through their own preburners","about 30 MPa","Raptor"],["Electric pump-fed","A battery-powered motor drives the pumps","limited by battery and motor power","Rutherford"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 7, 'callout', '{"kind":"key","title":"Trade in one line","text":"Higher chamber pressure allows a smaller nozzle, a higher thrust per engine mass and a better sea-level Isp, but it costs turbomachinery complexity, development time and risk."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'cycles', 8, 'callout', '{"kind":"tip","title":"Match cycle to size","text":"At the 10 to 50 kN class pressure-fed is the natural first engine; electric pumps are now practical when the pump power is a few tens of kW. Gas generators appear above a few hundred kN."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'cycles', 0, 'A cycle is just the answer to where the pumping power comes from.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'cycles', 1, 'Pressure-fed is simple but tank-limited to about 1 to 3 MPa.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'cycles', 2, 'Higher chamber pressure improves Isp and shrinks the engine but needs turbomachinery.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm1', 0, 'An engine has exit pressure equal to ambient pressure. What is its thrust?', '["$\\dot m v_e$ only","$\\dot m v_e + p_e A_e$","$\\dot m v_e - p_a A_e$","Zero"]', 0, 'With $p_e = p_a$ the pressure-thrust term $(p_e - p_a)A_e$ vanishes, leaving momentum thrust.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm1', 1, 'Which quantity best tests the quality of the injector and combustion chamber?', '["Thrust coefficient CF","$c^*$ efficiency","Nozzle area ratio","Tank pressure"]', 1, '$c^*$ depends on the combustion, not on the nozzle, so measured over ideal $c^*$ isolates the injector and chamber.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm1', 2, 'Why is a dense propellant pair often preferred for a first stage even with a lower Isp?', '["It burns hotter","It needs no pumps","Smaller, lighter tanks","It is hypergolic"]', 2, 'Tank mass and drag scale with volume. Dense propellants shrink tanks enough to offset a lower Isp.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm1', 3, 'A gas-generator cycle differs from staged combustion mainly because:', '["It needs no turbine","The turbine exhaust is dumped, not burned in the chamber","It uses a battery","It runs fuel-lean"]', 1, 'Dumping the turbine exhaust wastes a few percent of the propellant, which is the Isp price of the simpler cycle.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('liquid-rocket-engines', 'm2', 'Thrust chamber, nozzle and injector', 'Turn performance targets into a throat area, a chamber volume, a nozzle and a hole pattern.', 1);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'chamber-sizing', 'm2', 'Sizing the chamber', 35, 'From thrust and chamber pressure to throat area, mass flow, L* and chamber diameter.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 0, 'h', '{"text":"Start from three numbers"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 1, 'p', '{"text":"Pick the thrust $F$ you need, the chamber pressure $p_c$ you can afford (the tanks or pumps decide it), and a realistic $c^*$ and $C_F$ for the propellants and nozzle. Everything else follows."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 2, 'eq', '{"text":"A_t = \\frac{F}{C_F\\, p_c}, \\qquad \\dot m = \\frac{p_c A_t}{c^*}","name":"Throat area and mass flow"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 3, 'h', '{"text":"Chamber volume"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 4, 'p', '{"text":"The propellants need time to atomise, evaporate, mix and burn before reaching the throat. That time is set by the chamber volume $V_c$. The standard shortcut is the **characteristic length**."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 5, 'eq', '{"text":"L^* = \\frac{V_c}{A_t}","name":"Characteristic length"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 6, 'ul', '{"items":["LOX/RP-1 engines typically use $L^*$ of about 1.0 to 1.3 m.","LOX/hydrogen needs less, about 0.6 to 0.8 m, because hydrogen mixes and burns quickly.","A bigger $L^*$ improves combustion efficiency but adds wall area, mass and heat load."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 7, 'p', '{"text":"The chamber''s cross-section is set by the **contraction ratio** $A_c/A_t$, commonly 3 to 5 for small engines. A low ratio makes the gas accelerate early and causes a pressure drop in the chamber; a high one makes a fat, heavy chamber."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 8, 'h', '{"text":"Worked example: 18 kN at 2.5 MPa"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 9, 'p', '{"text":"Take a LOX/RP-1 engine with $p_c = 2.5$ MPa, $c^* = 1700$ m/s and an area ratio of 4, which expands the gas to about sea-level pressure with an ideal $C_F$ of 1.44. A nozzle efficiency of 97 percent gives $C_F \\approx 1.40$."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 10, 'ul', '{"items":["$A_t = 18\\,000 / (1.40 \\times 2.5\\times10^6) = 5.15\\times10^{-3}\\ \\mathrm{m^2} = 51.5\\ \\mathrm{cm^2}$, so the throat diameter is **81 mm**.","$\\dot m = 2.5\\times10^6 \\times 5.15\\times10^{-3} / 1700 = \\mathbf{7.58\\ kg/s}$, giving $I_{sp} = 18\\,000/(7.58 \\times 9.807) \\approx 242$ s at sea level.","With $L^* = 1.0$ m, $V_c = 5.15$ L. A contraction ratio of 4 gives a chamber diameter of $2\\times 81 = 162$ mm and a cylinder length of about 25 cm."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'chamber-sizing', 11, 'callout', '{"kind":"warn","title":"Do not skip the margin","text":"Real throats erode, heat expands them and manufacturing tolerances scatter them. A 2 percent change in $A_t$ is a 2 percent change in $p_c$ at fixed flow. Plan to calibrate the first engine and keep the throat insert replaceable."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'chamber-sizing', 0, '$A_t = F/(C_F p_c)$ and $\dot m = p_c A_t / c^*$ fix the size of the engine.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'chamber-sizing', 1, '$L^* = V_c/A_t$ gives the chamber volume; 1.0 to 1.3 m is typical for LOX/RP-1.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'chamber-sizing', 2, 'Chamber diameter comes from the contraction ratio, usually 3 to 5.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'nozzle-design', 'm2', 'Nozzle design', 30, 'Area ratio, optimum expansion, separation, and why bells beat cones.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 0, 'h', '{"text":"The nozzle is a gas accelerator"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 1, 'p', '{"text":"Gas reaches Mach 1 at the throat, then keeps accelerating as the diverging section lets it expand. The **area ratio** $\\varepsilon = A_e/A_t$ sets how far the pressure falls."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 2, 'eq', '{"text":"\\frac{A_e}{A_t} = \\frac{1}{M_e}\\left[\\frac{2}{\\gamma+1}\\left(1+\\frac{\\gamma-1}{2}M_e^2\\right)\\right]^{\\frac{\\gamma+1}{2(\\gamma-1)}}","name":"Area-Mach relation"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 3, 'p', '{"text":"For $\\gamma \\approx 1.22$ and $p_c = 2.5$ MPa, $\\varepsilon = 4$ expands the flow to $p_e \\approx 105$ kPa, about one atmosphere, and $\\varepsilon = 8$ to about 40 kPa."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 4, 'h', '{"text":"Optimum expansion"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 5, 'p', '{"text":"Thrust is largest when $p_e = p_a$. A nozzle for sea level has a small $\\varepsilon$; one for vacuum has a large one, because there is no ambient pressure to match."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 6, 'ul', '{"items":["**Under-expanded** ($p_e > p_a$): the gas leaves with pressure to spare. You lose thrust but nothing breaks.","**Over-expanded** ($p_e < p_a$): the thrust is lower, and if $p_e$ falls below about 0.3 to 0.4 of $p_a$ the flow **separates** from the wall. The separation line moves and oscillates, producing side loads that have damaged real engines."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 7, 'h', '{"text":"Contours"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 8, 'table', '{"head":["Shape","Length","Efficiency","Comment"],"rows":[["Conical, 15° half-angle","Long","$\\lambda = (1+\\cos\\alpha)/2 = 0.983$","Simple and cheap; good for small engines"],["Bell (parabolic, 80 percent)","80 percent of a 15° cone","About the same as the cone","Shorter and lighter; the standard choice"],["Dual bell or aerospike","Varies","Altitude-compensating","Heavy and complex; mostly research"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'nozzle-design', 9, 'callout', '{"kind":"tip","title":"Test with a short nozzle","text":"On a sea-level test stand, a vacuum-sized nozzle will flow-separate. Test a vacuum engine with a shortened nozzle or a diffuser, and extend afterwards."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'nozzle-design', 0, 'Area ratio sets the exit pressure; thrust peaks when $p_e = p_a$.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'nozzle-design', 1, 'Over-expanded nozzles separate below about 0.3 to 0.4 of ambient pressure and cause side loads.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'nozzle-design', 2, 'A 15° cone loses about 1.7 percent to divergence; an 80 percent bell matches it in a shorter length.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'injectors', 'm2', 'Injectors', 30, 'Atomising and mixing two liquids in a few milliseconds, and sizing the holes.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 0, 'h', '{"text":"What the injector must do"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 1, 'p', '{"text":"The injector feeds the propellants to the chamber, breaks them into droplets, mixes them and distributes them evenly across the face. It also decides most of the engine''s combustion efficiency and stability."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 2, 'table', '{"head":["Type","How it mixes","Typical use"],"rows":[["Impinging doublet or triplet","Jets collide and shatter","LOX/kerosene, small engines"],["Pintle","Radial and annular sheets meet","Throttleable engines; Merlin 1D, Apollo LM"],["Shear coaxial","Fast gas shears a slow liquid core","LOX/hydrogen and LOX/methane"],["Swirl coaxial","Swirling film spreads into a spray","Staged-combustion and cryogenic engines"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 3, 'h', '{"text":"Sizing the holes"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 4, 'p', '{"text":"Each flow is a liquid forced through orifices. Bernoulli''s equation with a discharge coefficient gives the velocity."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 5, 'eq', '{"text":"v = C_d\\sqrt{\\frac{2\\,\\Delta p}{\\rho}}, \\qquad A = \\frac{\\dot m}{C_d\\sqrt{2\\rho\\,\\Delta p}}","name":"Injector orifice"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 6, 'p', '{"text":"With $C_d = 0.7$ and $\\Delta p = 0.5$ MPa (20 percent of a 2.5 MPa chamber), LOX at 1 141 kg/m³ leaves at 20.7 m/s and RP-1 at 810 kg/m³ at 24.6 m/s."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 7, 'callout', '{"kind":"key","title":"Pressure drop buys stability","text":"An injector pressure drop of 15 to 25 percent of chamber pressure decouples the chamber from the feed system. A drop below about 10 percent is an invitation to chugging, which is why designers resist cutting it to save pump power."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'injectors', 8, 'callout', '{"kind":"warn","title":"Cleanliness and tolerance","text":"A 3 percent blockage in a few holes changes the local O/F and can burn a hole in the wall. Flow-test every injector with water before any hot fire, and record the pressure drop."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'injectors', 0, 'The injector sets combustion efficiency and much of the stability margin.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'injectors', 1, 'Orifice area is $A = \dot m / (C_d\sqrt{2\rho\Delta p})$.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'injectors', 2, 'Use an injector pressure drop of 15 to 25 percent of chamber pressure.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm2', 0, 'Throat area for a given thrust is found from:', '["$F/(C_F\\,p_c)$","$p_c/(F\\,C_F)$","$F\\,c^*/p_c$","$\\dot m\\,g_0/F$"]', 0, '$C_F = F/(p_c A_t)$, so $A_t = F/(C_F p_c)$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm2', 1, 'What does $L^*$ measure?', '["Chamber volume divided by throat area","Nozzle length divided by throat diameter","Chamber length divided by diameter","Exit area divided by throat area"]', 0, '$L^* = V_c/A_t$ is the length a straight tube of throat area would need to have the chamber''s volume, and it sets residence time.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm2', 2, 'A nozzle is over-expanded when:', '["$p_e > p_a$","$p_e < p_a$","$p_e = p_a$","The throat is choked"]', 1, 'Over-expanded means the exit pressure is below the ambient pressure; severe cases separate the flow.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm2', 3, 'Why keep injector pressure drop above 15 percent of chamber pressure?', '["It raises $c^*$ above ideal","It decouples chamber pressure from feed oscillations","It cools the wall","It reduces mass flow"]', 1, 'A stiff pressure drop makes the injector flow insensitive to chamber pressure oscillations, which protects against chugging.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('liquid-rocket-engines', 'm3', 'Cooling and materials', 'Keeping a 3 400 K flame inside a metal wall that melts below 1 400 K.', 2);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'heat-flux', 'm3', 'Heat flux and the thermal problem', 30, 'How much heat arrives at the wall, where it peaks, and what limits the design.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 0, 'h', '{"text":"The wall is the hardest part"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 1, 'p', '{"text":"The combustion gas is at about 3 400 to 3 600 K, but a copper wall softens near 800 K and steel near 1 100 K. The wall survives only because heat flows through it faster than it arrives, into a coolant that is far colder."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 2, 'eq', '{"text":"q = h_g\\,(T_{aw} - T_{wg})","name":"Convective heat flux to the wall","caption":"$T_{aw}$ is the adiabatic wall temperature, $T_{wg}$ the hot-gas-side wall temperature"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 3, 'p', '{"text":"With $h_g = 4\\,000\\ \\mathrm{W/m^2K}$, $T_{aw} = 3\\,300$ K and a wall at 700 K, the flux is $q = 10.4\\ \\mathrm{MW/m^2}$. Compare that to the sun at 0.001 MW/m²."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 4, 'h', '{"text":"Where it peaks"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 5, 'ul', '{"items":["The **throat** sees the highest flux, because the gas is fastest and the boundary layer is thinnest there.","The coefficient grows roughly as $p_c^{0.8}$ and falls slowly with throat diameter. Doubling chamber pressure raises heat flux by about 75 percent.","A staged-combustion engine at 20 MPa or more sees tens of MW/m², and the Space Shuttle Main Engine throat exceeded 100 MW/m²."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 6, 'h', '{"text":"Conduction through the wall"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 7, 'eq', '{"text":"\\Delta T_{wall} = \\frac{q\\,t}{k}","name":"Temperature drop across the wall"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 8, 'p', '{"text":"At 10 MW/m² through a 1.5 mm copper wall with $k = 320$ W/m·K, the drop is 47 K. Thin, conductive walls keep the hot face cool, which is why chamber walls are copper alloys, not steel."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'heat-flux', 9, 'callout', '{"kind":"key","title":"The two margins","text":"A design needs a margin on the hot-wall temperature (strength and oxidation) and on the coolant (boiling and coking). Whichever is smaller sets the operating limit."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'heat-flux', 0, 'Hot-gas heat flux is $q = h_g(T_{aw} - T_{wg})$ and peaks at the throat.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'heat-flux', 1, 'Flux rises roughly as $p_c^{0.8}$; high-pressure engines are far harder to cool.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'heat-flux', 2, 'Thin, high-conductivity walls keep the hot face temperature low.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'regen-cooling', 'm3', 'Cooling methods', 30, 'Regenerative, film, ablative and radiative cooling: what each costs and where each fits.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 0, 'h', '{"text":"Choose by thrust class and burn time"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 1, 'table', '{"head":["Method","How it works","Where it fits","Cost"],"rows":[["Regenerative","A propellant flows through channels in the wall before the injector","Long burns, high pressure","Pressure drop, manufacturing complexity"],["Film","Some propellant coats the wall as a cool layer","Hot spots; add to other methods","Lower $c^*$ and Isp"],["Ablative","A liner chars and erodes, carrying the heat away","Short burns, low cost, small engines","Single use, erosion changes the throat"],["Radiation","The wall glows and radiates heat","Low-pressure nozzle extensions, small thrusters","Needs refractory metal such as niobium"],["Heat-sink","A thick metal wall stores the heat","Very short test firings","Heavy"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 2, 'h', '{"text":"Regenerative cooling"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 3, 'p', '{"text":"The coolant is usually the fuel (RP-1, hydrogen or methane), and the heat it absorbs returns to the combustion chamber, which is why it is called regenerative. The first-order energy balance tells you how much hotter it gets."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 4, 'eq', '{"text":"Q = \\dot m_c\\, c_p\\, \\Delta T","name":"Coolant temperature rise"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 5, 'p', '{"text":"A jacket absorbing 0.6 MW into 2.3 kg/s of RP-1 with $c_p = 2.0$ kJ/kg·K warms it by 130 K. The coolant is not the limit here; the limit is the coolant-side wall temperature."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 6, 'callout', '{"kind":"warn","title":"Coking","text":"Kerosene decomposes into carbon deposits when the wall on the coolant side exceeds roughly 550 to 600 K. The deposits insulate the wall, the temperature rises, and the engine can burn through in a few seconds. Keep the coolant-side wall below this limit with adequate velocity."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'regen-cooling', 7, 'callout', '{"kind":"tip","title":"Start with ablative or film","text":"For a first 18 kN engine, an ablative chamber with a graphite throat insert is the cheapest route to a hot-fire test. Learn the combustion first, add regenerative cooling on the second design."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'regen-cooling', 0, 'Regenerative cooling suits long burns and high pressure; ablative suits short burns.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'regen-cooling', 1, 'Coolant temperature rise is $Q/(\dot m_c c_p)$.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'regen-cooling', 2, 'Kerosene coking limits the coolant-side wall to about 550 to 600 K.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'materials', 'm3', 'Chamber materials and manufacturing', 25, 'Copper, nickel, graphite and silica phenolic, and how additive manufacturing changed chamber design.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'materials', 0, 'h', '{"text":"The material trade"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'materials', 1, 'table', '{"head":["Material","Strong point","Typical use"],"rows":[["Copper alloys (CuCrZr, NARloy-Z, GRCop)","High thermal conductivity","Regeneratively cooled liners"],["Inconel 718","Strength at temperature, weldable","Jackets, injector bodies, turbine parts"],["Stainless steel 304L or 316","Cheap, easy to machine and weld","Heat-sink and ablative shells, tanks"],["Graphite or carbon/carbon","Survives over 3 000 K","Throat inserts"],["Silica or carbon phenolic","Chars and insulates","Ablative liners"],["Niobium C-103","Refractory, radiates well","Radiation-cooled nozzle extensions"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'materials', 2, 'h', '{"text":"How chambers are made"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'materials', 3, 'ul', '{"items":["**Machined channels:** slots are milled in a copper liner and closed with electroformed nickel or a brazed jacket.","**Additive manufacturing:** laser powder bed fusion prints the entire chamber with cooling channels in one piece, in copper alloys or Inconel. It is behind the Rutherford and SuperDraco engines.","**Brazed tubes:** a bundle of thin tubes is brazed into the chamber shape; an older technique still used for large nozzles."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'materials', 4, 'callout', '{"kind":"key","title":"Inspect what you cannot see","text":"Internal channels cannot be seen after assembly. Flow-test every jacket for pressure drop, and use CT or dye penetrant checks on printed parts, before the first hot fire."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'materials', 5, 'callout', '{"kind":"warn","title":"Oxygen compatibility","text":"Many metals burn in hot, high-pressure oxygen. Oxidiser-side hardware needs cleaning to oxygen standard and materials that are proven for oxygen service, such as Inconel, copper alloys and certain stainless steels."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'materials', 0, 'Copper alloys carry the heat; nickel superalloys carry the load.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'materials', 1, 'Graphite throat inserts are the usual answer for the worst heat flux in an ablative engine.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'materials', 2, 'Additive manufacturing prints cooling channels that machining cannot reach.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm3', 0, 'Where in a thrust chamber is heat flux highest?', '["Injector face","Cylindrical chamber","Throat","Nozzle exit"]', 2, 'The gas velocity and heat transfer coefficient peak at the throat, where the boundary layer is thinnest.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm3', 1, 'Doubling chamber pressure raises heat flux by roughly:', '["No change","40 percent","75 percent","Four times"]', 2, 'Heat flux scales as $p_c^{0.8}$, and $2^{0.8} \approx 1.74$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm3', 2, 'Why is copper used for regeneratively cooled liners?', '["It is strongest","It conducts heat well, keeping the hot face cool","It is the cheapest","It resists oxidation"]', 1, '$\Delta T = qt/k$, so high conductivity $k$ gives a smaller temperature drop across the wall.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm3', 3, 'Which cooling method suits a short test burn of a first low-cost engine?', '["Full regenerative cooling","Ablative liner with a graphite throat","Radiation cooling","Cryogenic film cooling"]', 1, 'An ablative liner needs no cooling jacket and survives a few tens of seconds, the cheapest route to a hot-fire test.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('liquid-rocket-engines', 'm4', 'Feed systems', 'Getting propellants to the injector: pressure-fed tanks, turbopumps and cavitation.', 3);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'pressure-fed', 'm4', 'Pressure-fed systems', 30, 'Add up the pressure losses to find the tank pressure, then see what it costs in mass.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 0, 'h', '{"text":"Tank pressure budget"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 1, 'p', '{"text":"The tank pressure must exceed the chamber pressure by every pressure drop along the way."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 2, 'eq', '{"text":"p_{tank} = p_c + \\Delta p_{inj} + \\Delta p_{cool} + \\Delta p_{lines} + \\Delta p_{valves}","name":"Tank pressure budget"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 3, 'table', '{"head":["Item","Typical value","Example (MPa)"],"rows":[["Chamber pressure","set by the design","2.5"],["Injector drop","15 to 25 percent of pc","0.5"],["Cooling jacket (fuel side)","10 to 30 percent of pc","0.4"],["Lines, valves and filters","0.1 to 0.5 MPa","0.3"],["**Tank pressure**","","**3.7**"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 4, 'h', '{"text":"Pressurant"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 5, 'p', '{"text":"Helium is the usual pressurant, stored at 20 to 30 MPa in a composite bottle and regulated down to the tank pressure. It is light and does not dissolve in propellants, but it is expensive and needs a regulator that can survive the cold of expanding gas."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 6, 'ul', '{"items":["**Blowdown** needs no regulator but the tank pressure, and therefore thrust, falls through the burn.","**Regulated** keeps the pressure constant at the cost of a regulator and a separate bottle.","**Autogenous** pressurisation vaporises a little of the propellant (for example LOX in a heat exchanger) and avoids carrying helium."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pressure-fed', 7, 'callout', '{"kind":"warn","title":"Tank mass","text":"Wall thickness grows with $p_{tank} r/\\sigma$. Wall thickness is proportional to pressure, so a 3.7 MPa tank needs walls about 12 times thicker than a 0.3 MPa tank, until minimum-gauge limits apply. This is why pressure-fed vehicles are limited to small stages."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'pressure-fed', 0, 'Add every pressure drop from the injector back to the tank to size tank pressure.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'pressure-fed', 1, 'Helium is the usual pressurant; blowdown trades regulator mass for varying thrust.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'pressure-fed', 2, 'Tank mass rises with pressure, which limits pressure-fed engines.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'turbopumps', 'm4', 'Turbopumps and cavitation', 35, 'Pump power, head, and the one failure that can destroy a pump in a second: cavitation.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 0, 'h', '{"text":"Pump power"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 1, 'eq', '{"text":"P_{pump} = \\frac{\\dot m\\,\\Delta p}{\\rho\\,\\eta}","name":"Hydraulic power required"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 2, 'p', '{"text":"RP-1 at 2.3 kg/s, 4 MPa rise and 60 percent pump efficiency needs 18.9 kW. LOX at 5.3 kg/s needs 31 kW. Together about 50 kW, which an electric motor can supply for a small engine; a large engine needs a turbine of tens of MW."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 3, 'h', '{"text":"Turbine"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 4, 'p', '{"text":"The turbine takes its power from hot gas. The available power is limited by the gas flow, temperature and pressure ratio, and the turbine inlet temperature is limited by the blade material, typically 900 to 1 100 K. That is why gas generators run **fuel-rich**, to keep the gas cool."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 5, 'h', '{"text":"Cavitation"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 6, 'p', '{"text":"If the pressure at the pump inlet falls below the vapour pressure, the liquid boils in the low-pressure region of the impeller. The vapour bubbles collapse in the higher-pressure region downstream, which erodes the metal and, worse, chokes the flow."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 7, 'eq', '{"text":"NPSH_a = \\frac{p_{in} - p_v}{\\rho g} + \\frac{v^2}{2g}","name":"Net positive suction head available"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 8, 'p', '{"text":"A pump needs $NPSH_a$ above its own required value $NPSH_r$ with margin. A LOX tank at 300 kPa absolute with vapour pressure 101 kPa gives $NPSH_a = 17.8$ m before velocity head."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 9, 'ul', '{"items":["An **inducer**, a small axial stage in front of the impeller, lets the pump tolerate some cavitation.","Higher tank pressure or a subcooled propellant raises $NPSH_a$.","During the engine start the tanks sit at their lowest pressure, which is the most dangerous moment."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'turbopumps', 10, 'callout', '{"kind":"key","title":"Tank pressure is a pump requirement","text":"Even a pump-fed engine has pressurised tanks. The pressure is not for the chamber; it is to keep the pump inlet above the vapour pressure."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'turbopumps', 0, 'Pump power is $\dot m\,\Delta p/(\rho\eta)$.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'turbopumps', 1, 'Gas generators run fuel-rich to hold turbine temperature below about 1 100 K.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'turbopumps', 2, 'Cavitation is prevented by $NPSH_a > NPSH_r$, set by tank pressure and inducer design.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('liquid-rocket-engines', 'turbopumps', 0, 'Liquid rocket engine turbopump inducers (SP-8052)', 'NASA', 'https://ntrs.nasa.gov/search?q=liquid%20rocket%20engine%20turbopump%20inducers', 'A NASA design criteria monograph');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm4', 0, 'The tank pressure for a pressure-fed engine must be at least:', '["Chamber pressure","Chamber pressure plus all feed-line, cooling and injector drops","Twice the chamber pressure","Atmospheric plus 0.1 MPa"]', 1, 'Each stage of the feed path loses pressure, so the tank must supply the chamber pressure plus all of those drops.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm4', 1, 'Which pressurisation method lets thrust fall during the burn?', '["Regulated helium","Autogenous","Blowdown","Turbopump"]', 2, 'In blowdown the gas expands as the liquid leaves, so the pressure and thrust fall.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm4', 2, 'What causes pump cavitation?', '["Pump speed too low","Inlet pressure close to or below the vapour pressure","Discharge pressure too high","Using cryogenic propellants only"]', 1, 'Vapour forms when the local pressure is below the vapour pressure, and the bubbles collapse downstream.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm4', 3, 'Why do gas-generator turbines run fuel-rich?', '["To increase $c^*$","To cool the gas to a temperature the turbine blades can survive","To save oxidiser","To raise pump efficiency"]', 1, 'Stoichiometric gas would be above 3 000 K. Running fuel-rich brings it to about 900 K.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('liquid-rocket-engines', 'm5', 'Combustion stability and pogo', 'Three kinds of oscillation, the physics that drives them, and how to stop them.', 4);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'instability-types', 'm5', 'Chugging, buzz and screech', 30, 'Sort oscillations by frequency, find the mechanism, and match it with a remedy.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 0, 'h', '{"text":"A flame is an amplifier"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 1, 'p', '{"text":"Combustion releases heat. If the heat release rises when the pressure rises, the oscillation grows. This is the **Rayleigh criterion**, and it explains every instability in this lesson."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 2, 'table', '{"head":["Type","Frequency","Mechanism","Remedy"],"rows":[["Chugging","10 to 200 Hz","Chamber pressure couples with the feed system (flow lags pressure)","Raise injector pressure drop, reduce feed-line compliance"],["Buzz","200 to 1 000 Hz","Injector flow couples with chamber pressure at intermediate frequency","Stiffer injector, change orifice length"],["Screech","1 000 Hz and above","Acoustic standing waves in the chamber (tangential or radial) reinforce heat release","Baffles, acoustic cavities, injector changes"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 3, 'h', '{"text":"Estimating acoustic frequencies"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 4, 'p', '{"text":"Screech frequencies follow the chamber''s acoustic modes. The speed of sound in the hot products is about 1 200 m/s."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 5, 'eq', '{"text":"f_{1T} \\approx \\frac{0.586\\,a}{D}, \\qquad f_{1L} = \\frac{a}{2L}","name":"First tangential and first longitudinal modes"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 6, 'p', '{"text":"For the 162 mm chamber, $f_{1T} \\approx 0.586 \\times 1200 / 0.162 = 4.3$ kHz. A 25 cm chamber has $f_{1L} \\approx 2.4$ kHz."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 7, 'callout', '{"kind":"warn","title":"Screech destroys engines","text":"High-frequency instability raises wall heat flux several-fold within milliseconds. An engine can go from healthy to a burned-through chamber in under a second. It is why injector design is still an empirical craft, and why the F-1 programme spent years on bomb-stability testing."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 8, 'h', '{"text":"Defences"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'instability-types', 9, 'ul', '{"items":["**Baffles**, blades that stand out from the injector face, break up the transverse acoustic modes.","**Acoustic cavities** (Helmholtz resonators) in the wall absorb energy at a tuned frequency.","A stiff **injector pressure drop** isolates the chamber from the feed system.","**Dynamic stability rating**: pulse the chamber with a small explosive or a pulse gun and check that the pressure disturbance decays within a few milliseconds."]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'instability-types', 0, 'The Rayleigh criterion: heat release in phase with pressure amplifies oscillation.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'instability-types', 1, 'Frequency tells you the mechanism: chugging is low, screech is acoustic and high.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'instability-types', 2, 'Baffles, cavities and a stiff injector are the main defences.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'pogo-coupling', 'm5', 'Pogo: engine meets structure', 25, 'How a feedback loop closes through the vehicle''s own structure.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pogo-coupling', 0, 'h', '{"text":"A loop with three parts"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pogo-coupling', 1, 'p', '{"text":"Pogo is not a combustion instability. It is a **structural** oscillation, at 5 to 50 Hz, that is sustained by the engine and the propellant lines. The loop has three parts: the structure, the feed line and the engine."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pogo-coupling', 2, 'ol', '{"items":["The vehicle''s first longitudinal mode moves the engine and tanks.","That motion changes the pressure at the pump inlet and the flow in the feed line.","The flow change alters chamber pressure and thrust.","The thrust oscillation pushes on the structure, in phase with the motion if the loop gain is high enough."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pogo-coupling', 3, 'h', '{"text":"How to stop it"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pogo-coupling', 4, 'ul', '{"items":["**Detune** the feed-line frequency away from the structural frequency, by changing line length or compliance.","Add a **gas-filled accumulator** to the oxidiser line, a soft cushion that absorbs the pressure change. The Space Shuttle main engines used one on the LOX line, and the Saturn V centre engine was fitted with a helium-filled one after Apollo 13.","Run a **stability analysis**, with the transfer function of each element, before the first flight."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pogo-coupling', 5, 'callout', '{"kind":"key","title":"Chugging is not pogo","text":"Chugging couples the chamber and the feed system with no structural mode involved. Pogo needs the structure. The two can look alike on a sensor, so check the frequency against the structural mode."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'pogo-coupling', 6, 'p', '{"text":"The structures course goes deeper into pogo from the vehicle side: see the lessons on the pogo mechanism and its suppression in *Structures, Vibration and Dynamic Environments*."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'pogo-coupling', 0, 'Pogo is a structure-propulsion feedback loop at 5 to 50 Hz, not a combustion instability.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'pogo-coupling', 1, 'An accumulator on the oxidiser line, or detuning the lines, breaks the loop.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'pogo-coupling', 2, 'Chugging involves no structural mode; check the frequency to tell them apart.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm5', 0, 'The Rayleigh criterion says an oscillation grows when:', '["Pressure falls as heat release rises","Heat release rises in phase with pressure","Mass flow is steady","The chamber is cooled"]', 1, 'Heat added when pressure is highest does work on the gas and feeds the oscillation.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm5', 1, 'A 4 kHz oscillation in a chamber 160 mm in diameter is most likely:', '["Chugging","Pogo","Screech","Water hammer"]', 2, 'Kilohertz oscillations match the chamber''s acoustic modes, which is screech.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm5', 2, 'Which of these is a remedy for chugging?', '["Acoustic cavities","Raising the injector pressure drop","Adding baffles","Using a longer nozzle"]', 1, 'A stiffer injector decouples the chamber from feed-system pressure oscillations.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm5', 3, 'Pogo oscillates at roughly:', '["0.1 Hz","5 to 50 Hz","1 to 5 kHz","Above 10 kHz"]', 1, 'Pogo occurs at the first longitudinal structural mode, typically 5 to 50 Hz.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('liquid-rocket-engines', 'm6', 'Capstone: size an 18 kN engine', 'Put the whole course into one hand calculation.', 5);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('liquid-rocket-engines', 'size-18kn', 'm6', 'Capstone: size an 18 kN LOX/RP-1 engine', 60, 'Throat, chamber, nozzle, injector, feed pressure, cooling and stability checks for one small engine, with every number traced.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 0, 'h', '{"text":"The brief"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 1, 'ul', '{"items":["Thrust 18 kN at sea level, burn time 40 s, LOX/RP-1.","Pressure-fed, ablative chamber with a graphite throat insert, helium pressurant.","Assumptions: $p_c = 2.5$ MPa, O/F = 2.3, $c^* = 1\\,700$ m/s, $C_F = 1.40$ (area ratio 4, 97 percent nozzle efficiency), $L^* = 1.0$ m."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 2, 'h', '{"text":"Step 1: performance and flows"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 3, 'ul', '{"items":["$A_t = F/(C_F p_c) = 51.5\\ \\mathrm{cm^2}$, so the throat diameter is **81 mm**.","$\\dot m = p_c A_t / c^* = \\mathbf{7.58\\ kg/s}$, so $I_{sp} \\approx 242$ s at sea level.","$\\dot m_{ox} = 5.28$ kg/s and $\\dot m_f = 2.30$ kg/s.","Propellant for 40 s: 211 kg LOX and 92 kg RP-1."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 4, 'h', '{"text":"Step 2: chamber and nozzle"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 5, 'ul', '{"items":["$V_c = L^* A_t = 5.15$ L; with contraction ratio 4 the chamber diameter is **162 mm**, the cylinder length about 25 cm.","Area ratio 4: $A_e = 206\\ \\mathrm{cm^2}$, so the exit diameter is **162 mm**, and $p_e \\approx 105$ kPa."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 6, 'h', '{"text":"Step 3: injector"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 7, 'p', '{"text":"At $\\Delta p = 0.5$ MPa (20 percent of $p_c$) and $C_d = 0.7$:"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 8, 'table', '{"head":["Propellant","Flow (kg/s)","Area needed","Holes","Velocity (m/s)"],"rows":[["LOX (1 141 kg/m³)","5.28","223 mm²","32 × Ø3.0 mm","20.7"],["RP-1 (810 kg/m³)","2.30","115 mm²","24 × Ø2.5 mm","24.6"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 9, 'h', '{"text":"Step 4: feed pressure and pressurant"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 10, 'p', '{"text":"Tank pressure: 2.5 + 0.5 (injector) + 0.3 (lines and valves) = 3.3 MPa for an ablative chamber with no cooling jacket, so plan about **3.5 MPa** with margin. A regeneratively cooled version would add about 0.4 MPa for the jacket."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 11, 'h', '{"text":"Step 5: thermal and stability checks"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 12, 'ul', '{"items":["Throat heat flux about 10 MW/m². An ablative liner is acceptable for 40 s; use a graphite insert.","First tangential mode $\\approx 4.3$ kHz. Plan a baffle test or a pulse-gun stability rating before extended burns.","Pressure drop across the injector is 20 percent of chamber pressure, so the chugging margin is adequate."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 13, 'callout', '{"kind":"key","title":"What you have produced","text":"A complete first-order engine definition, in a page of arithmetic. The next steps are detailed design, an injector water-flow test, a short hot fire and then calibration of $c^*$ and throat area from the measured pressure."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('liquid-rocket-engines', 'size-18kn', 14, 'callout', '{"kind":"tip","title":"Check it in code","text":"The databank for this course has a Python snippet that reproduces these numbers. Change thrust or chamber pressure and see how the engine size, flow and hole count change."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'size-18kn', 0, 'A first-order engine sizing is a chain of simple formulas: $A_t$, $\dot m$, $V_c$, area ratio, orifices, tank pressure.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'size-18kn', 1, 'Every step has a check: heat flux, acoustic modes, injector pressure drop and NPSH.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('liquid-rocket-engines', 'size-18kn', 2, 'Hot-fire data replaces assumptions: measure $p_c$ and $\dot m$ to compute the real $c^*$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm6', 0, 'For F = 18 kN, pc = 2.5 MPa and CF = 1.40, the throat area is about:', '["12 cm²","51 cm²","180 cm²","720 cm²"]', 1, '$A_t = 18\,000/(1.40 \times 2.5\times10^6) = 5.14\times10^{-3}\ \mathrm{m^2} = 51.4\ \mathrm{cm^2}$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm6', 1, 'For O/F = 2.3 and total flow 7.58 kg/s, the LOX flow is:', '["2.30 kg/s","3.30 kg/s","5.28 kg/s","7.58 kg/s"]', 2, '$\dot m_{ox} = 7.58 \times 2.3/3.3 = 5.28$ kg/s.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('liquid-rocket-engines', 'm6', 2, 'After the first hot fire, what do you do with the measured chamber pressure and flow?', '["Discard them","Compute the real $c^*$ and calibrate the throat area","Increase O/F","Skip the injector test"]', 1, '$c^* = p_c A_t/\dot m$ with measured values replaces the assumed $c^*$ and corrects every later calculation.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 0, 'Thrust', 'm1', 'The force an engine exerts on the vehicle: $F = \dot m v_e + (p_e - p_a)A_e$.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 1, 'Specific impulse (Isp)', 'm1', 'Thrust per unit weight flow of propellant, in seconds. Higher is more efficient.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 2, 'Characteristic velocity (c*)', 'm1', '$p_c A_t/\dot m$. A measure of combustion quality that does not depend on the nozzle.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 3, 'Thrust coefficient (CF)', 'm1', '$F/(p_c A_t)$. A measure of nozzle quality that does not depend on the combustion.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 4, 'Mixture ratio (O/F)', 'm1', 'Mass flow of oxidiser divided by mass flow of fuel.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 5, 'Gas generator cycle', 'm1', 'A pump-fed cycle in which a small burner drives the turbine and its exhaust is dumped overboard.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 6, 'Staged combustion', 'm1', 'A pump-fed cycle in which preburner exhaust is routed into the main chamber, so no propellant is wasted.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 7, 'Expander cycle', 'm1', 'A pump-fed cycle in which the fuel is heated in the cooling jacket and expanded through the turbine.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 8, 'Area ratio', 'm2', '$\varepsilon = A_e/A_t$. Sets how far the nozzle expands the gas.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 9, 'Over-expansion', 'm2', 'The nozzle exit pressure is below ambient pressure. Thrust falls and severe cases separate the flow.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 10, 'Characteristic length (L*)', 'm2', 'Chamber volume divided by throat area; sets the propellant residence time.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 11, 'Contraction ratio', 'm2', 'Chamber cross-section area divided by throat area.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 12, 'Discharge coefficient (Cd)', 'm2', 'The ratio of actual to ideal flow through an orifice, about 0.6 to 0.8 for injector holes.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 13, 'Pintle injector', 'm2', 'An injector that forms radial and annular sheets that collide to mix; good for throttling.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 14, 'Regenerative cooling', 'm3', 'Cooling the chamber wall with one of the propellants before it is injected.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 15, 'Film cooling', 'm3', 'Injecting a layer of propellant along the wall to insulate it from the hot gas.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 16, 'Ablative cooling', 'm3', 'A liner that chars and erodes, carrying heat away as it is lost.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 17, 'Coking', 'm3', 'Carbon deposits left when kerosene decomposes on a hot wall; they insulate and overheat the wall.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 18, 'NPSH', 'm4', 'Net positive suction head: the margin of the pump inlet pressure over the vapour pressure, as a column of liquid.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 19, 'Cavitation', 'm4', 'Vapour bubbles forming where the pressure is below vapour pressure and collapsing downstream, which damages pumps.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 20, 'Inducer', 'm4', 'A low-pressure axial stage ahead of a pump impeller that lets it work with less inlet head.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 21, 'Chugging', 'm5', 'Low-frequency (10 to 200 Hz) combustion oscillation caused by coupling with the feed system.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 22, 'Screech', 'm5', 'High-frequency (kHz) combustion instability from acoustic modes in the chamber.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 23, 'Rayleigh criterion', 'm5', 'An oscillation is amplified when heat release is in phase with pressure.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 24, 'Pogo', 'm5', 'A structural oscillation sustained by the engine and propellant lines at 5 to 50 Hz.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('liquid-rocket-engines', 25, 'Accumulator', 'm5', 'A gas-filled volume on a feed line that absorbs pressure pulses to break a pogo loop.');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('liquid-rocket-engines', 0, 'Rocket Propulsion Elements (Sutton and Biblarz)', 'Wiley', NULL, 'The standard textbook; chapters 3 to 11 cover this course');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('liquid-rocket-engines', 1, 'Design of Liquid Propellant Rocket Engines (Huzel and Huang), NASA SP-125', 'NASA', 'https://ntrs.nasa.gov/search?q=NASA%20SP-125%20Design%20of%20Liquid%20Propellant%20Rocket%20Engines', 'The classic hands-on design reference');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('liquid-rocket-engines', 2, 'Liquid rocket engine injectors, NASA SP-8089', 'NASA', 'https://ntrs.nasa.gov/search?q=liquid%20rocket%20engine%20injectors%20SP-8089', 'Design criteria monograph');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('liquid-rocket-engines', 3, 'Liquid rocket engine combustion stabilization devices, NASA SP-8113', 'NASA', 'https://ntrs.nasa.gov/search?q=liquid%20rocket%20engine%20combustion%20stabilization%20devices', 'Baffles and acoustic cavities');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('liquid-rocket-engines', 4, 'Prevention of coupled structure-propulsion instability (pogo), NASA SP-8055', 'NASA', 'https://ntrs.nasa.gov/search?q=prevention%20of%20coupled%20structure-propulsion%20instability', 'The standard pogo reference');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('liquid-rocket-engines', 5, 'Rocket Propulsion (NPTEL video course)', 'IIT Madras (Prof. K. Ramamurthi)', 'https://nptel.ac.in/', 'Search the NPTEL catalogue for the course');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('liquid-rocket-engines', 6, 'Aerospace Propulsion (NPTEL video course)', 'IIT Madras (Dr P. A. Ramakrishna)', 'https://nptel.ac.in/', 'Lectures 31 to 38 cover liquid rockets');
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'isp-def', 'm1', 'Isp and effective exhaust velocity', '$I_{sp} = F/(\dot m g_0)$, so $v_{eff} = I_{sp}\,g_0$. A 300 s engine has $v_{eff} \approx 2\,940$ m/s.', 0);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'cstar-values', 'm1', 'Typical c* values', 'LOX/RP-1: about **1 700 to 1 800 m/s**. LOX/LH2: about **2 300 to 2 400 m/s**. LOX/methane: about **1 800 to 1 850 m/s**.', 1);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'of-ratios', 'm1', 'Typical O/F', 'LOX/RP-1: **2.2 to 2.8**. LOX/methane: **3.2 to 3.6**. LOX/LH2: **5 to 6**. N2O4/UDMH: **2.0 to 2.5**.', 2);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'lstar', 'm2', 'Characteristic length', '$L^* = V_c/A_t$: LOX/RP-1 **1.0 to 1.3 m**, LOX/LH2 **0.6 to 0.8 m**.', 3);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'inj-dp', 'm2', 'Injector pressure drop', 'Use **15 to 25 percent** of chamber pressure. Below 10 percent invites chugging.', 4);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'sep', 'm2', 'Flow separation limit', 'Over-expanded flow separates when $p_e < 0.3\text{–}0.4\,p_a$ (Summerfield criterion).', 5);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'q-scaling', 'm3', 'Heat flux scaling', '$q \propto p_c^{0.8}$, peaking at the throat. 2.5 MPa gives about 10 MW/m²; large staged-combustion engines exceed 100.', 6);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'coke', 'm3', 'Kerosene coking limit', 'Keep the coolant-side wall of an RP-1 jacket below roughly **550 to 600 K**.', 7);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'pump-power', 'm4', 'Pump power', '$P = \dot m\,\Delta p/(\rho\eta)$. Efficiency 0.5 to 0.7 for small pumps.', 8);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'npsh', 'm4', 'NPSH', '$NPSH_a = (p_{in} - p_v)/(\rho g) + v^2/(2g)$. Keep it above $NPSH_r$ with margin.', 9);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'acoustics', 'm5', 'Chamber acoustic modes', '$f_{1T} \approx 0.586\,a/D$, $f_{1L} = a/(2L)$, with $a \approx 1\,200$ m/s in LOX/RP-1 products.', 10);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('liquid-rocket-engines', 'pogo-band', 'm5', 'Pogo frequency band', '**5 to 50 Hz**: the first longitudinal structural mode, coupled through the feed line.', 11);
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('liquid-rocket-engines', 'py-size', 'm6', 'Size a thrust chamber', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('liquid-rocket-engines', 'py-acoustic', 'm5', 'Chamber acoustic modes', 'python', 'import numpy as np
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('liquid-rocket-engines', 'm1-problems', 'm1', 'Performance problems', 'Thrust, Isp, mass ratio and cycles.', 'mixed', 0);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm1-problems', 'm1-problems-1', 0, 'numeric', 1, 'An engine has total flow 10 kg/s and exhaust velocity 2 500 m/s with $p_e = p_a$. What is its thrust?', NULL, '$F = \dot m v_e = 10 \times 2\,500 = 25\,000$ N = 25 kN.', NULL, NULL, 25, 0.02, 'kN');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm1-problems', 'm1-problems-2', 1, 'numeric', 1, 'An 18 kN engine burns 7.58 kg/s. What is its specific impulse?', NULL, '$I_{sp} = F/(\dot m g_0) = 18\,000/(7.58 \times 9.807) = 242$ s.', NULL, NULL, 242, 0.02, 's');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm1-problems', 'm1-problems-3', 2, 'numeric', 2, 'A stage has Isp 300 s and a mass ratio $m_0/m_f = 4$. What is $\Delta v$?', NULL, '$\Delta v = 300 \times 9.80665 \times \ln 4 = 4\,078$ m/s.', NULL, NULL, 4078.5, 0.02, 'm/s');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm1-problems', 'm1-problems-4', 3, 'mcq', 2, 'Why is the best Isp reached with a fuel-rich mixture?', NULL, 'Lighter exhaust molecules give a higher exhaust velocity for the same energy, so best Isp sits on the fuel-rich side of stoichiometric.', '["Fuel is cheaper","Light exhaust molecules raise exhaust velocity","Oxidiser lowers pressure","It lowers heat flux only"]', 1, NULL, NULL, NULL);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm1-problems', 'm1-problems-5', 4, 'mcq', 3, 'An expander cycle is limited to modest thrust mainly because:', NULL, 'The turbine power comes from heat picked up in the wall. At a fixed L* the wall area grows roughly with the engine diameter, but the pump power needed grows with thrust, roughly the diameter squared, so beyond a few hundred kN the jacket cannot supply enough heat.', '["It cannot use pumps","The heat absorbed in the cooling jacket is limited, so turbine power is limited","It needs helium","It is not reusable"]', 1, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('liquid-rocket-engines', 'm2-problems', 'm2', 'Chamber and injector problems', 'Throat area, c*, injector velocity and nozzle loss.', 'problems', 1);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm2-problems', 'm2-problems-1', 0, 'numeric', 1, 'What throat area does an 18 kN engine need at $p_c = 2.5$ MPa and $C_F = 1.40$?', NULL, '$A_t = F/(C_F p_c) = 18\,000/(1.40 \times 2.5\times10^6) = 5.14\times10^{-3}$ m² = 51.4 cm².', NULL, NULL, 51.4, 0.03, 'cm²');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm2-problems', 'm2-problems-2', 1, 'numeric', 1, 'A chamber at 2.5 MPa with throat area 51.5 cm² flows 7.58 kg/s. What is $c^*$?', NULL, '$c^* = p_c A_t/\dot m = 2.5\times10^6 \times 5.15\times10^{-3}/7.58 = 1\,698$ m/s.', NULL, NULL, 1700, 0.02, 'm/s');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm2-problems', 'm2-problems-3', 2, 'numeric', 2, 'LOX (1 141 kg/m³) is injected through orifices with $C_d = 0.7$ and $\Delta p = 0.5$ MPa. What is the jet velocity?', NULL, '$v = C_d\sqrt{2\Delta p/\rho} = 0.7\sqrt{2 \times 5\times10^5/1141} = 20.7$ m/s.', NULL, NULL, 20.7, 0.02, 'm/s');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm2-problems', 'm2-problems-4', 3, 'numeric', 1, 'What is the divergence factor of a conical nozzle with a 15° half-angle?', NULL, '$\lambda = (1 + \cos 15^\circ)/2 = (1 + 0.9659)/2 = 0.983$.', NULL, NULL, 0.983, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm2-problems', 'm2-problems-5', 4, 'mcq', 2, 'A sea-level nozzle has $p_e = 20$ kPa at $p_a = 101$ kPa. What is the likely result?', NULL, '$p_e/p_a = 0.2$ is below the Summerfield limit of about 0.3 to 0.4, so the flow separates.', '["Perfect expansion","Under-expansion","Over-expansion, probably with flow separation","Choked flow in the nozzle"]', 2, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('liquid-rocket-engines', 'm3-problems', 'm3', 'Thermal problems', 'Heat flux, wall temperature drop and coolant rise.', 'problems', 2);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm3-problems', 'm3-problems-1', 0, 'numeric', 1, 'A gas-side coefficient of 4 000 W/m²K, adiabatic wall temperature 3 300 K and a wall at 700 K. What is the heat flux?', NULL, '$q = h(T_{aw} - T_{wg}) = 4000 \times 2600 = 10.4\times10^6$ W/m².', NULL, NULL, 10.4, 0.02, 'MW/m²');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm3-problems', 'm3-problems-2', 1, 'numeric', 1, '10 MW/m² flows through a 1.5 mm copper wall with $k = 320$ W/m·K. What is the temperature drop across the wall?', NULL, '$\Delta T = qt/k = 10^7 \times 0.0015/320 = 46.9$ K.', NULL, NULL, 46.9, 0.02, 'K');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm3-problems', 'm3-problems-3', 2, 'numeric', 2, 'A cooling jacket absorbs 0.6 MW into 2.3 kg/s of RP-1 with $c_p = 2.0$ kJ/kg·K. By how much does the coolant warm?', NULL, '$\Delta T = Q/(\dot m c_p) = 6\times10^5/(2.3 \times 2000) = 130.4$ K.', NULL, NULL, 130.4, 0.02, 'K');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm3-problems', 'm3-problems-4', 3, 'mcq', 2, 'What is the main danger of running an RP-1 coolant-side wall above about 600 K?', NULL, 'Carbon deposits form, lower the heat transfer into the coolant and push the wall temperature up in a runaway.', '["Freezing","Coking, which insulates the wall and raises its temperature","Cavitation","Corrosion of the injector"]', 1, NULL, NULL, NULL);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm3-problems', 'm3-problems-5', 4, 'written', 2, 'Compare film cooling with ablative cooling for a short-burn small engine. Give one advantage and one disadvantage of each.', NULL, '**Film cooling.** Advantage: no consumable liner, so it can be reused and reduces local hot spots. Disadvantage: the film propellant burns incompletely, which lowers $c^*$ and Isp by a few percent.
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('liquid-rocket-engines', 'm4-problems', 'm4', 'Feed-system problems', 'Tank pressure, pump power and cavitation margin.', 'problems', 3);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm4-problems', 'm4-problems-1', 0, 'numeric', 1, 'Chamber pressure is 2.5 MPa, injector drop 0.5 MPa, cooling jacket drop 0.4 MPa and lines and valves 0.3 MPa. What tank pressure does a pressure-fed system need?', NULL, 'Add the chamber pressure and all the drops: 2.5 + 0.5 + 0.4 + 0.3 = 3.7 MPa.', NULL, NULL, 3.7, 0.02, 'MPa');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm4-problems', 'm4-problems-2', 1, 'numeric', 1, 'RP-1 (810 kg/m³) flows 2.3 kg/s through a pump raising pressure by 4 MPa at 60 percent efficiency. What power does it need?', NULL, '$P = \dot m \Delta p/(\rho\eta) = 2.3 \times 4\times10^6/(810 \times 0.6) = 18.9$ kW.', NULL, NULL, 18.9, 0.02, 'kW');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm4-problems', 'm4-problems-3', 2, 'numeric', 2, 'A LOX pump inlet is at 300 kPa absolute; the vapour pressure is 101 kPa and the density 1 141 kg/m³. What is $NPSH_a$ (ignore velocity head)?', NULL, '$NPSH_a = (p - p_v)/(\rho g) = (300\,000 - 101\,000)/(1141 \times 9.81) = 17.8$ m.', NULL, NULL, 17.8, 0.03, 'm');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm4-problems', 'm4-problems-4', 3, 'mcq', 2, 'Which change reduces the risk of pump cavitation?', NULL, 'An inducer raises the pressure gently ahead of the impeller, letting the pump work at lower $NPSH_a$.', '["Lower tank pressure","Higher propellant temperature","An inducer ahead of the impeller","A smaller inlet line"]', 2, NULL, NULL, NULL);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm4-problems', 'm4-problems-5', 4, 'written', 2, 'Why does a pump-fed engine still need pressurised tanks?', NULL, 'The tank pressure is not there to feed the chamber but to keep the pump inlet pressure above the vapour pressure by the required NPSH. Without it the propellant boils at the pump inlet and the pump cavitates, especially at engine start when pressure is lowest.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('liquid-rocket-engines', 'm5-problems', 'm5', 'Stability problems', 'Acoustic modes and telling the instabilities apart.', 'mixed', 4);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm5-problems', 'm5-problems-1', 0, 'numeric', 1, 'A chamber has diameter 0.162 m and $a = 1\,200$ m/s. What is the first tangential frequency, $f \approx 0.586\,a/D$?', NULL, '$f = 0.586 \times 1200/0.162 = 4\,341$ Hz = 4.34 kHz.', NULL, NULL, 4.34, 0.03, 'kHz');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm5-problems', 'm5-problems-2', 1, 'mcq', 2, 'A 60 Hz oscillation in chamber pressure that disappears when the injector pressure drop is doubled is most likely:', NULL, 'A low-frequency oscillation that depends on the injector stiffness is chugging.', '["Screech","Chugging","A turbine blade pass","Water hammer"]', 1, NULL, NULL, NULL);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm5-problems', 'm5-problems-3', 2, 'mcq', 2, 'Which defence works against screech but not against chugging?', NULL, 'Baffles and cavities act on the chamber''s acoustic modes; chugging is a feed-system coupling.', '["Baffles and acoustic cavities","A stiffer injector","A pressurised tank","Smaller feed lines"]', 0, NULL, NULL, NULL);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm5-problems', 'm5-problems-4', 3, 'written', 3, 'State the Rayleigh criterion and apply it to explain why a small pressure disturbance can grow into screech.', NULL, 'The Rayleigh criterion says an acoustic oscillation grows when heat release is in phase with the pressure oscillation: heat added at the pressure peak does work on the gas. In a chamber, droplet vaporisation and burning rates rise with pressure, so heat release follows the pressure wave. If the gain exceeds the acoustic damping, each cycle is larger than the last, and the standing wave grows into screech.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('liquid-rocket-engines', 'm5-problems', 'm5-problems-5', 4, 'written', 3, 'Why is pogo not a combustion instability, and how would you tell chugging from pogo on a flight recording?', NULL, 'Pogo needs the vehicle''s structural mode: engine thrust oscillation excites the longitudinal mode, whose motion modulates the feed-line pressure, which feeds back into thrust. Chugging couples only the chamber and the feed system. On a recording, pogo appears at the structure''s longitudinal frequency (5 to 50 Hz) and shows up as an axial acceleration oscillation, while chugging is set by the feed system and chamber volume and appears in the chamber pressure without an accelerometer signature at the structural mode.', NULL, NULL, NULL, NULL, NULL);
