-- Course: Liquid Rocket Engines


F, pc, cstar, CF = 18_000.0, 2.5e6, 1_700.0, 1.40   # N, Pa, m/s, -
OF, Lstar, CR, dp, Cd = 2.3, 1.0, 4.0, 0.5e6, 0.7
rho = {"ox": 1141.0, "f": 810.0}

At = F / (CF * pc)
mdot = pc * At / cstar
m_ox, m_f = mdot * OF / (1 + OF), mdot / (1 + OF)
dt = np.sqrt(4 * At / np.pi)
Vc = Lstar * At
print(f"At = {At*1e4:.1f} cm2, dt = {dt*1e3:.0f} mm, mdot = {mdot:.2f} kg/s, Isp = {F/mdot/9.80665:.0f} s")
print(f"Vc = {Vc*1e3:.2f} L, chamber D = {dt*np.sqrt(CR)*1e3:.0f} mm")
for name, m in (("ox", m_ox), ("f", m_f)):
    A = m / (Cd * np.sqrt(2 * rho[name] * dp))
    print(f"{name}: {m:.2f} kg/s, orifice area {A*1e6:.0f} mm2, v = {m/(rho[name]*A):.1f} m/s")', 'Change F, pc or O/F and watch every dimension update', 0);

gamma, R, T = 1.22, 361.0, 3_400.0        # approximate LOX/RP-1 products
a = np.sqrt(gamma * R * T)
D, L = 0.162, 0.25
print(f"a = {a:.0f} m/s")
print(f"first tangential  : {0.586*a/D/1e3:.2f} kHz")
print(f"first longitudinal: {a/(2*L)/1e3:.2f} kHz")', 'Compare with the screech frequency seen on a high-rate pressure sensor', 1);

**Ablative.** Advantage: simple and cheap, needs no coolant channels. Disadvantage: single use, and erosion enlarges the throat, so chamber pressure and thrust drift during the burn.', NULL, NULL, NULL, NULL, NULL);
